  synchronized String encodePathComponents(String[] path, int length) {
    pathEncodeCount++;
    if (length == 0) {
      pathEncodeBuffer.setLength(0);
      return "";
    }
    pathEncodeBuffer.setLength(0);
    char delim = FacetsConfig.DELIM_CHAR;
    char escape = FacetsConfig.ESCAPE_CHAR;
    for (int i = 0; i < length; i++) {
      String s = path[i];
      if (s.length() == 0) {
        throw new IllegalArgumentException("each path component must have length > 0 (got: \"\")");
      }
      int numChars = s.length();
      for (int j = 0; j < numChars; j++) {
        char ch = s.charAt(j);
        if (ch == delim || ch == escape) {
          pathEncodeBuffer.append(escape);
        }
        pathEncodeBuffer.append(ch);
      }
      pathEncodeBuffer.append(delim);
    }
    pathEncodeBuffer.setLength(pathEncodeBuffer.length() - 1);
    return pathEncodeBuffer.toString();
  }

  synchronized String encodeDimPath(String dim, String... path) {
    pathEncodeCount++;
    if (path.length == 0) {
      return encodePathComponents(new String[] {dim}, 1);
    }
    String[] fullPath = new String[1 + path.length];
    fullPath[0] = dim;
    System.arraycopy(path, 0, fullPath, 1, path.length);
    return encodePathComponents(fullPath, fullPath.length);
  }

  synchronized String[] decodePathComponents(String s) {
    pathDecodeCount++;
    pathEncodeCount++;
    pathDecodeParts.clear();
    int length = s.length();
    if (length == 0) {
      return new String[0];
    }
    char delim = FacetsConfig.DELIM_CHAR;
    char escape = FacetsConfig.ESCAPE_CHAR;
    if (pathDecodeBuffer == null || pathDecodeBuffer.length < length) {
      pathDecodeBuffer = new char[length];
    }
    int upto = 0;
    boolean lastEscape = false;
    for (int i = 0; i < length; i++) {
      char ch = s.charAt(i);
      if (lastEscape) {
        pathDecodeBuffer[upto++] = ch;
        lastEscape = false;
      } else if (ch == escape) {
        lastEscape = true;
      } else if (ch == delim) {
        pathDecodeParts.add(new String(pathDecodeBuffer, 0, upto));
        upto = 0;
      } else {
        pathDecodeBuffer[upto++] = ch;
      }
    }
    pathDecodeParts.add(new String(pathDecodeBuffer, 0, upto));
    assert !lastEscape;
    return pathDecodeParts.toArray(new String[0]);
  }

  void initializeLongCounters() {
    if (longInitialized) {
      return;
    }
    assert longCounts == null && longHashCounts == null;
    longInitialized = true;
    longCounts = new int[1024];
    longHashCounts = new LongIntHashMap();
  }

  void incrementLongValue(long value) {
    if (value >= 0 && value < longCounts.length) {
      longCounts[(int) value]++;
    } else {
      longHashCounts.addTo(value, 1);
    }
  }

  void countLongValues(LongValuesSource valueSource, List<MatchingDocs> matchingDocs)
      throws IOException {
    for (MatchingDocs hits : matchingDocs) {
      if (hits.totalHits == 0) {
        continue;
      }
      initializeLongCounters();
      org.apache.lucene.search.LongValues fv = valueSource.getValues(hits.context, null);
      DocIdSetIterator docs = hits.bits.iterator();
      for (int doc = docs.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; ) {
        if (fv.advanceExact(doc)) {
          incrementLongValue(fv.longValue());
          longTotCount++;
        }
        doc = docs.nextDoc();
      }
    }
  }

  void countLongMultiValues(MultiLongValuesSource valuesSource, List<MatchingDocs> matchingDocs)
      throws IOException {
    for (MatchingDocs hits : matchingDocs) {
      if (hits.totalHits == 0) {
        continue;
      }
      initializeLongCounters();
      MultiLongValues multiValues = valuesSource.getValues(hits.context);
      DocIdSetIterator docs = hits.bits.iterator();
      for (int doc = docs.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; ) {
        if (multiValues.advanceExact(doc)) {
          long limit = multiValues.getValueCount();
          if (limit > 0) {
            longTotCount++;
          }
          long previousValue = 0;
          for (int i = 0; i < limit; i++) {
            long value = multiValues.nextValue();
            if (i == 0 || value != previousValue) {
              incrementLongValue(value);
              previousValue = value;
            }
          }
        }
        doc = docs.nextDoc();
      }
    }
  }

  void countLongField(String countedField, List<MatchingDocs> matchingDocs) throws IOException {
    for (MatchingDocs hits : matchingDocs) {
      if (hits.totalHits == 0) {
        continue;
      }
      initializeLongCounters();
      SortedNumericDocValues multiValues =
          DocValues.getSortedNumeric(hits.context.reader(), countedField);
      NumericDocValues singleValues = DocValues.unwrapSingleton(multiValues);
      if (singleValues != null) {
        DocIdSetIterator it =
            ConjunctionUtils.intersectIterators(Arrays.asList(hits.bits.iterator(), singleValues));
        for (int doc = it.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; doc = it.nextDoc()) {
          incrementLongValue(singleValues.longValue());
          longTotCount++;
        }
      } else {
        DocIdSetIterator it =
            ConjunctionUtils.intersectIterators(Arrays.asList(hits.bits.iterator(), multiValues));
        for (int doc = it.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; doc = it.nextDoc()) {
          int limit = multiValues.docValueCount();
          if (limit > 0) {
            longTotCount++;
          }
          long previousValue = 0;
          for (int i = 0; i < limit; i++) {
            long value = multiValues.nextValue();
            if (i == 0 || value != previousValue) {
              incrementLongValue(value);
              previousValue = value;
            }
          }
        }
      }
    }
  }

  void countAllLongValues(IndexReader indexReader, LongValuesSource valueSource) throws IOException {
    for (LeafReaderContext context : indexReader.leaves()) {
      org.apache.lucene.search.LongValues fv = valueSource.getValues(context, null);
      int maxDoc = context.reader().maxDoc();
      for (int doc = 0; doc < maxDoc; doc++) {
        if (fv.advanceExact(doc)) {
          incrementLongValue(fv.longValue());
          longTotCount++;
        }
      }
    }
  }

