  void countAllLongField(IndexReader indexReader, String countedField) throws IOException {
    for (LeafReaderContext context : indexReader.leaves()) {
      SortedNumericDocValues multiValues =
          DocValues.getSortedNumeric(context.reader(), countedField);
      NumericDocValues singleValues = DocValues.unwrapSingleton(multiValues);
      Bits liveDocs = context.reader().getLiveDocs();
      DocIdSetIterator valuesIt = singleValues != null ? singleValues : multiValues;
      valuesIt = (liveDocs != null) ? FacetUtils.liveDocsDISI(valuesIt, liveDocs) : valuesIt;
      if (singleValues != null) {
        for (int doc = valuesIt.nextDoc();
            doc != DocIdSetIterator.NO_MORE_DOCS;
            doc = valuesIt.nextDoc()) {
          longTotCount++;
          incrementLongValue(singleValues.longValue());
        }
      } else {
        for (int doc = valuesIt.nextDoc();
            doc != DocIdSetIterator.NO_MORE_DOCS;
            doc = valuesIt.nextDoc()) {
          int limit = multiValues.docValueCount();
          if (limit > 0) {
            longTotCount++;
          }
          long previousValue = 0;
          for (int i = 0; i < limit; i++) {
            long value = multiValues.nextValue();
            if (i == 0 || value != previousValue) {
              incrementLongValue(value);
              previousValue = value;
            }
          }
        }
      }
    }
  }

  FacetResult longGetAllChildren(String dim, String... path) {
    validateLongDimAndPath(dim, path);
    if (longInitialized == false) {
      assert longTotCount == 0;
      return new FacetResult(longField, new String[0], longTotCount, new LabelAndValue[0], 0);
    }
    List<LabelAndValue> labelValues = new ArrayList<>();
    for (int i = 0; i < longCounts.length; i++) {
      if (longCounts[i] != 0) {
        labelValues.add(new LabelAndValue(Long.toString(i), longCounts[i]));
      }
    }
    if (longHashCounts.size() != 0) {
      for (LongIntHashMap.LongIntCursor c : longHashCounts) {
        int count = c.value;
        if (count != 0) {
          labelValues.add(new LabelAndValue(Long.toString(c.key), c.value));
        }
      }
    }
    return new FacetResult(
        longField,
        new String[0],
        longTotCount,
        labelValues.toArray(new LabelAndValue[0]),
        labelValues.size());
  }

  FacetResult longGetTopChildren(int topN, String dim, String... path) {
    validateTopN(topN);
    validateLongDimAndPath(dim, path);
    if (longInitialized == false) {
      assert longTotCount == 0;
      return new FacetResult(longField, new String[0], longTotCount, new LabelAndValue[0], 0);
    }
    PriorityQueue<LongCountEntry> pq =
        new PriorityQueue<>(Math.min(topN, longCounts.length + longHashCounts.size())) {
          @Override
          protected boolean lessThan(LongCountEntry a, LongCountEntry b) {
            return a.count < b.count || (a.count == b.count && a.value > b.value);
          }
        };
    int childCount = 0;
    LongCountEntry e = null;
    for (int i = 0; i < longCounts.length; i++) {
      if (longCounts[i] != 0) {
        childCount++;
        if (e == null) {
          e = new LongCountEntry();
        }
        e.value = i;
        e.count = longCounts[i];
        e = pq.insertWithOverflow(e);
      }
    }
    if (longHashCounts.size() != 0) {
      childCount += longHashCounts.size();
      for (LongIntHashMap.LongIntCursor c : longHashCounts) {
        int count = c.value;
        if (count != 0) {
          if (e == null) {
            e = new LongCountEntry();
          }
          e.value = c.key;
          e.count = count;
          e = pq.insertWithOverflow(e);
        }
      }
    }
    LabelAndValue[] results = new LabelAndValue[pq.size()];
    while (pq.size() != 0) {
      LongCountEntry entry = pq.pop();
      results[pq.size()] = new LabelAndValue(Long.toString(entry.value), entry.count);
    }
    return new FacetResult(longField, new String[0], longTotCount, results, childCount);
  }

  FacetResult longGetAllChildrenSortByValue() {
    if (longInitialized == false) {
      assert longTotCount == 0;
      return new FacetResult(longField, new String[0], longTotCount, new LabelAndValue[0], 0);
    }
    List<LabelAndValue> labelValues = new ArrayList<>();
    int[] sortedHashCounts = new int[longHashCounts.size()];
    long[] sortedHashValues = new long[longHashCounts.size()];
    int upto = 0;
    for (LongIntHashMap.LongIntCursor c : longHashCounts) {
      if (c.value != 0) {
        sortedHashCounts[upto] = c.value;
        sortedHashValues[upto] = c.key;
        upto++;
      }
    }
    assert upto == longHashCounts.size()
        : "upto=" + upto + " hashCounts.size=" + longHashCounts.size();
    new InPlaceMergeSorter() {
      @Override
      public int compare(int i, int j) {
        return Long.compare(sortedHashValues[i], sortedHashValues[j]);
      }

      @Override
      public void swap(int i, int j) {
        int x = sortedHashCounts[i];
        sortedHashCounts[i] = sortedHashCounts[j];
        sortedHashCounts[j] = x;
        long y = sortedHashValues[j];
        sortedHashValues[j] = sortedHashValues[i];
        sortedHashValues[i] = y;
      }
    }.sort(0, upto);
    boolean countsAdded = false;
    for (int i = 0; i < upto; i++) {
      if (countsAdded == false && sortedHashValues[i] >= longCounts.length) {
        countsAdded = true;
        appendLongCounts(labelValues);
      }
      labelValues.add(new LabelAndValue(Long.toString(sortedHashValues[i]), sortedHashCounts[i]));
    }
    if (countsAdded == false) {
      appendLongCounts(labelValues);
    }
    return new FacetResult(
        longField,
        new String[0],
        longTotCount,
        labelValues.toArray(new LabelAndValue[0]),
        labelValues.size());
  }

  void appendLongCounts(List<LabelAndValue> labelValues) {
    for (int i = 0; i < longCounts.length; i++) {
      if (longCounts[i] != 0) {
        labelValues.add(new LabelAndValue(Long.toString(i), longCounts[i]));
      }
    }
  }

  void validateLongDimAndPath(String dim, String... path) {
    if (dim.equals(longField) == false) {
      throw new IllegalArgumentException(
          "invalid dim \"" + dim + "\"; should be \"" + longField + "\"");
    }
    if (path.length != 0) {
      throw new IllegalArgumentException("path.length should be 0");
    }
  }

  List<FacetResult> longGetAllDims(int topN) {
    validateTopN(topN);
    return Collections.singletonList(longGetTopChildren(topN, longField));
  }

  String longCountsToString() {
    StringBuilder b = new StringBuilder();
    b.append("LongValueFacetCounts totCount=");
    b.append(longTotCount);
    if (longInitialized) {
      b.append(":\n");
      for (int i = 0; i < longCounts.length; i++) {
        if (longCounts[i] != 0) {
          b.append("  ");
          b.append(i);
          b.append(" -> count=");
          b.append(longCounts[i]);
          b.append('\n');
        }
      }
      if (longHashCounts.size() != 0) {
        for (LongIntHashMap.LongIntCursor c : longHashCounts) {
          if (c.value != 0) {
            b.append("  ");
            b.append(c.key);
            b.append(" -> count=");
            b.append(c.value);
            b.append('\n');
          }
        }
      }
    }
    return b.toString();
  }

  DocIdSetIterator buildFilteredIterator(
      Query fastMatchQuery, MatchingDocs hits, DocIdSetIterator... iterators) throws IOException {
    boundFastMatchQuery = fastMatchQuery;
    boundIteratorList.clear();
    boundIteratorList.add(hits.bits.iterator());
    boundIteratorList.addAll(Arrays.asList(iterators));
    if (boundIteratorList.stream().anyMatch(Objects::isNull)) {
      return null;
    }
    if (addFastMatchIterator(hits) == false) {
      return null;
    }
    return intersectBoundIterators();
  }

  boolean addFastMatchIterator(MatchingDocs hits) throws IOException {
    if (boundFastMatchQuery == null) {
      return true;
    }
    final IndexReaderContext topLevelContext = ReaderUtil.getTopLevelContext(hits.context);
    final IndexSearcher searcher = new IndexSearcher(topLevelContext);
    searcher.setQueryCache(null);
    final Weight fastMatchWeight =
        searcher.createWeight(
            searcher.rewrite(boundFastMatchQuery), ScoreMode.COMPLETE_NO_SCORES, 1);
    final Scorer s = fastMatchWeight.scorer(hits.context);
    if (s == null) {
      return false;
    }
    boundIteratorList.add(s.iterator());
    return true;
  }

  DocIdSetIterator intersectBoundIterators() {
    if (boundIteratorList.size() == 1) {
      return boundIteratorList.get(0);
    }
    return ConjunctionUtils.intersectIterators(boundIteratorList);
  }

  FacetResult assembleRangeAllChildren(
      String dim, String[] path, String fieldName, String[] labels, int[] counts, int totCount) {
    bindRangeResult(dim, path, fieldName, labels, counts, totCount, labels.length);
    validateRangeDimAndPath();
    LabelAndValue[] labelValues = new LabelAndValue[rangeLabels.length];
    if (rangeCountValues == null) {
      for (int i = 0; i < rangeLabels.length; i++) {
        labelValues[i] = new LabelAndValue(rangeLabels[i], 0);
      }
    } else {
      for (int i = 0; i < rangeLabels.length; i++) {
        labelValues[i] = new LabelAndValue(rangeLabels[i], rangeCountValues[i]);
      }
    }
    return new FacetResult(dim, path, rangeTotCount, labelValues, labelValues.length);
  }

  FacetResult assembleRangeTopChildren(
      int topN,
      String dim,
      String[] path,
      String fieldName,
      String[] labels,
      int[] counts,
      int totCount) {
    bindRangeResult(dim, path, fieldName, labels, counts, totCount, topN);
    validateRangeDimAndPath();
    if (rangeCountValues == null) {
      assert rangeTotCount == 0;
      return new FacetResult(dim, path, rangeTotCount, new LabelAndValue[0], 0);
    }
    PriorityQueue<RangeCountEntry> pq =
        new PriorityQueue<>(Math.min(rangeTopN, rangeCountValues.length)) {
          @Override
          protected boolean lessThan(RangeCountEntry a, RangeCountEntry b) {
            int cmp = Integer.compare(a.count, b.count);
            if (cmp == 0) {
              cmp = b.label.compareTo(a.label);
            }
            return cmp < 0;
          }
        };
    int childCount = 0;
    RangeCountEntry e = null;
    for (int i = 0; i < rangeCountValues.length; i++) {
      if (rangeCountValues[i] != 0) {
        childCount++;
        if (e == null) {
          e = new RangeCountEntry();
        }
        e.label = rangeLabels[i];
        e.count = rangeCountValues[i];
        e = pq.insertWithOverflow(e);
      }
    }
    LabelAndValue[] results = new LabelAndValue[pq.size()];
    while (pq.size() != 0) {
      RangeCountEntry entry = pq.pop();
      results[pq.size()] = new LabelAndValue(entry.label, entry.count);
    }
    return new FacetResult(dim, path, rangeTotCount, results, childCount);
  }

  void bindRangeResult(
      String dim,
      String[] path,
      String fieldName,
      String[] labels,
      int[] counts,
      int totCount,
      int topN) {
    rangeFieldName = fieldName;
    rangeRequestDim = dim;
    rangeRequestPath = path;
    rangeLabels = labels;
    rangeCountValues = counts;
    rangeTotCount = totCount;
    rangeTopN = topN;
  }

  void validateRangeDimAndPath() {
    if (rangeRequestDim.equals(rangeFieldName) == false) {
      throw new IllegalArgumentException(
          "invalid dim \"" + rangeRequestDim + "\"; should be \"" + rangeFieldName + "\"");
    }
    if (rangeRequestPath.length != 0) {
      throw new IllegalArgumentException("path.length should be 0");
    }
  }

  String describeBoundRanges(String fieldName, String[] labels, int[] counts, int totCount) {
    bindRangeResult(fieldName, new String[0], fieldName, labels, counts, totCount, 0);
    StringBuilder b = new StringBuilder();
    b.append("RangeFacetCounts totCount=");
    b.append(rangeTotCount);
    b.append(":\n");
    for (int i = 0; i < rangeLabels.length; i++) {
      b.append("  ");
      b.append(rangeLabels[i]);
      b.append(" -> count=");
      b.append(rangeCountValues != null ? rangeCountValues[i] : 0);
      b.append('\n');
    }
    return b.toString();
  }

